package com.panish.ridebooking.rider.service;
import com.fasterxml.jackson.databind.ObjectMapper; import com.panish.ridebooking.events.RideRequestedEvent; import com.panish.ridebooking.rider.domain.OutboxEvent; import com.panish.ridebooking.rider.repository.OutboxEventRepository; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Component public class OutboxPublisher {private final OutboxEventRepository repository; private final KafkaTemplate<String,Object> kafka; private final ObjectMapper mapper; public OutboxPublisher(OutboxEventRepository r,KafkaTemplate<String,Object> k,ObjectMapper m){repository=r;kafka=k;mapper=m;} @Scheduled(fixedDelayString="${outbox.poll-ms:1000}") public void publish(){List<OutboxEvent> events=repository.findTop100ByPublishedFalseOrderByCreatedAtAsc(); for(OutboxEvent e:events){try{RideRequestedEvent event=mapper.readValue(e.getPayload(),RideRequestedEvent.class);kafka.send(e.getTopic(),event.eventId(),event).get();markPublished(e.getId());}catch(Exception ex){System.err.println("Outbox publish failed for "+e.getId()+": "+ex.getMessage());}}} @Transactional public void markPublished(String id){repository.findById(id).ifPresent(e->{e.markPublished();repository.save(e);});}}